import os, pandas as pd; import numpy as np;
path = os.path.join(os.environ['WORKSPACE_DATA'], 'daily_bars', 'part-000.parquet');
df = pd.read_parquet(path);
# Pivot to wide format
wide = df.pivot(index='session_date', columns='asset_id', values='close').ffill();
# Compute 5-day returns (excluding today, which we cannot observe)
rets = wide.pct_change(periods=5).iloc[-2];
print(rets.to_string())
